CREATE VIEW v_cards_sets AS SELECT cards.id AS card_id, cards.name AS card_name, cards.asciiName AS ascii_name, cards.uuid, cards.artist, cards.borderColor AS border_color, cards.colors, cards.convertedManaCost AS converted_mana_cost, cards.faceName AS face_name, cards.flavorText AS flavor_text, cards.keywords, cards.layout, cards.manaCost AS mana_cost, cards.power, cards.rarity, cards.setCode AS set_code, cards.side, cards.subtypes, cards.supertypes, cards.text AS card_text, cards.toughness, cards.type AS card_type, cards.types, sets.name AS set_name, sets.block AS set_block, sets.releaseDate AS set_release_date, sets.totalSetSize AS total_set_size, sets.type AS set_type, cards.availability, cards.cardKingdomFoilId, cards.cardKingdomId, cards.duelDeck, cards.edhrecRank, cards.frameVersion, cards.hasContentWarning, cards.isPromo, cards.isStorySpotlight, cards.isTextless, cards.originalType, sets.id, sets.baseSetSize, sets.code, sets.isForeignOnly, sets.mcmName, sets.mtgoCode FROM cards LEFT JOIN sets ON cards.setCode = sets.code;

CREATE VIEW v_cards_legalities AS SELECT cards.id AS card_id, cards.name AS card_name, cards.uuid, cards.setCode AS set_code, cards.type AS card_type, cards.rarity, legalities.format AS legality_format, legalities.status AS legality_status, cards.artist, cards.availability, cards.borderColor, cards.cardKingdomFoilId, cards.cardKingdomId, cards.colors, cards.convertedManaCost, cards.duelDeck, cards.edhrecRank, cards.frameVersion, cards.hasContentWarning, cards.isPromo, cards.isStorySpotlight, cards.isTextless, cards.layout, cards.manaCost, cards.originalType, cards.power, cards.side, cards.subtypes, cards.supertypes, cards.types, legalities.uuid AS legalities_uuid FROM cards LEFT JOIN legalities ON cards.uuid = legalities.uuid;

CREATE VIEW v_set_translations AS SELECT sets.id AS set_id, sets.code AS set_code, sets.name AS set_name, sets.releaseDate AS set_release_date, set_translations.language AS translation_language, set_translations.translation AS set_translation, sets.baseSetSize, sets.block, sets.isForeignOnly, sets.mcmName, sets.mtgoCode, set_translations.setCode FROM sets LEFT JOIN set_translations ON sets.code = set_translations.setCode;

CREATE VIEW v_cards_foreign_data AS SELECT cards.id, cards.artist, cards.availability, cards.borderColor, cards.cardKingdomFoilId, cards.cardKingdomId, cards.colors, cards.convertedManaCost, cards.duelDeck, cards.edhrecRank, cards.frameVersion, cards.hasContentWarning, cards.isPromo, cards.isStorySpotlight, cards.isTextless, cards.layout, cards.manaCost, cards.name, cards.originalType, cards.power, cards.rarity, cards.setCode, cards.side, cards.subtypes, cards.supertypes, cards.type, cards.types, cards.uuid, foreign_data.flavorText, foreign_data.language, foreign_data.multiverseid, foreign_data.name AS foreign_data_name, foreign_data.text, foreign_data.uuid AS foreign_data_uuid FROM cards INNER JOIN foreign_data ON cards.uuid = foreign_data.uuid;

CREATE VIEW v_cards_foreign_data_sets AS SELECT cards.id, cards.artist, cards.availability, cards.borderColor, cards.cardKingdomFoilId, cards.cardKingdomId, cards.colors, cards.convertedManaCost, cards.duelDeck, cards.edhrecRank, cards.frameVersion, cards.hasContentWarning, cards.isPromo, cards.isStorySpotlight, cards.isTextless, cards.layout, cards.manaCost, cards.name, cards.originalType, cards.power, cards.rarity, cards.setCode, cards.side, cards.subtypes, cards.supertypes, cards.type, cards.types, cards.uuid, foreign_data.flavorText, foreign_data.language, foreign_data.multiverseid, foreign_data.name AS foreign_data_name, foreign_data.text, foreign_data.uuid AS foreign_data_uuid, sets.id AS sets_id, sets.baseSetSize, sets.block, sets.code, sets.isForeignOnly, sets.mcmName, sets.mtgoCode, sets.name AS sets_name FROM cards INNER JOIN foreign_data ON cards.uuid = foreign_data.uuid INNER JOIN sets ON cards.setcode = sets.code;

CREATE VIEW v_cards_legalities_rulings AS SELECT cards.id, cards.artist, cards.availability, cards.borderColor, cards.cardKingdomFoilId, cards.cardKingdomId, cards.colors, cards.convertedManaCost, cards.duelDeck, cards.edhrecRank, cards.frameVersion, cards.hasContentWarning, cards.isPromo, cards.isStorySpotlight, cards.isTextless, cards.layout, cards.manaCost, cards.name, cards.originalType, cards.power, cards.rarity, cards.setCode, cards.side, cards.subtypes, cards.supertypes, cards.type, cards.types, cards.uuid, legalities.format, legalities.status, legalities.uuid AS legalities_uuid, rulings.text, rulings.uuid AS rulings_uuid FROM cards INNER JOIN legalities ON cards.uuid = legalities.uuid INNER JOIN rulings ON cards.uuid = rulings.uuid;

CREATE VIEW v_cards_rulings AS SELECT cards.id, cards.artist, cards.availability, cards.borderColor, cards.cardKingdomFoilId, cards.cardKingdomId, cards.colors, cards.convertedManaCost, cards.duelDeck, cards.edhrecRank, cards.frameVersion, cards.hasContentWarning, cards.isPromo, cards.isStorySpotlight, cards.isTextless, cards.layout, cards.manaCost, cards.name, cards.originalType, cards.power, cards.rarity, cards.setCode, cards.side, cards.subtypes, cards.supertypes, cards.type, cards.types, cards.uuid, rulings.text, rulings.uuid AS rulings_uuid FROM cards INNER JOIN rulings ON cards.uuid = rulings.uuid;

CREATE VIEW v_cards_set_translations AS SELECT cards.id, cards.artist, cards.availability, cards.borderColor, cards.cardKingdomFoilId, cards.cardKingdomId, cards.colors, cards.convertedManaCost, cards.duelDeck, cards.edhrecRank, cards.frameVersion, cards.hasContentWarning, cards.isPromo, cards.isStorySpotlight, cards.isTextless, cards.layout, cards.manaCost, cards.name, cards.originalType, cards.power, cards.rarity, cards.setCode, cards.side, cards.subtypes, cards.supertypes, cards.type, cards.types, cards.uuid, set_translations.language, set_translations.setCode AS set_translations_setCode, set_translations.translation FROM cards INNER JOIN set_translations ON cards.setcode = set_translations.setcode;

CREATE VIEW v_foreign_data AS SELECT foreign_data.flavorText, foreign_data.language, foreign_data.multiverseid, foreign_data.name, foreign_data.text, foreign_data.uuid FROM foreign_data;
